import type { ReactNode, SVGProps } from "react";

// Stroke icons copied from docs/design (24×24 grid, currentColor).
function Stroke({
  size = 16,
  width = 1.8,
  children,
  ...rest
}: {
  size?: number;
  width?: number;
  children: ReactNode;
} & SVGProps<SVGSVGElement>) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={width}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...rest}
    >
      {children}
    </svg>
  );
}

type P = { size?: number };

